"""Additional publication content shared by Word, Markdown and in-app readers."""

UPDATED = '2026-11-09'
CONTACT = 'h82292245@gmail.com'


def extend_documents(docs, policy):
    new = [
        ('16_Advertising_and_Sponsored_Content_Policy.docx', 'Advertising and Sponsored Content Policy', 'Privacy and advertising',
         'How advertising may fund the free Alphajournal workspace, what users can control, and how commercial messages are distinguished from product content.', [
            ('Planned service', 'Google AdSense is the selected advertising provider for a future free-version rollout. No AdSense publisher tag or ad requests are enabled by this implementation. Inventory, regional eligibility and paid-plan treatment must be confirmed before activation. A cookie choice alone does not activate an advertising service.'),
            ('Where advertisements may appear', 'Use clearly labelled Advertisement or Sponsored placements in approved general-content areas. Do not place ads in sign-in, billing, deletion, consent, private messages, journal editors, private research, AI conversations, sensitive financial views or security workflows. Keep distance from navigation and destructive controls to prevent accidental clicks. Placement must not cover content, imitate alerts or interrupt saving work.'),
            ('Information and consent', 'Before enabling AdSense, disclose data sent to Google, all active storage, geographic processing and controls. Optional advertising defaults off. Personalisation additionally requires its own affirmative choice. Non-personalised ads can still need storage and consent. A certified Google CMP is a deployment dependency in the regions covered by Google requirements. The product preference screen does not replace that CMP.'),
            ('Protected workspace information', 'Never pass private account data, holdings, balances, journal or note text, uploaded documents, messages, AI prompts, credentials, tax identifiers or payout details as ad parameters. Do not place AdSense on private-content routes where page scanning could expose such information. Validate the actual network payloads, URLs and referrers, not only source-level configuration.'),
            ('Your controls', 'Open Help and policies, then Cookie preferences. You may reject all optional processing, permit advertising without personalisation, or change your choices later. Essential account use remains available. Changes apply on this device. Google provides additional controls at https://myadcenter.google.com/ and information at https://policies.google.com/technologies/partner-sites. These external controls supplement the app choices.'),
            ('Commercial independence', 'An ad is not a recommendation, verification of a broker or promise of returns. Advertisers control the destinations of their ads. Review their terms and privacy practices before sharing information or transacting. Paid partners and community sponsors must disclose their relationship near the relevant content.'),
            ('Free and paid plans', 'The free version may carry ads when enabled. The checkout must state the advertising treatment of every paid plan. We do not promise an ad-free paid experience until the plan and delivery system enforce it. Browser installation does not change your plan, ad eligibility or privacy choices.'),
            ('Invalid traffic and reports', 'Do not repeatedly click ads, use automation to inflate impressions, encourage clicks to support the app or reward ordinary ad interaction. Report deceptive or unsafe ads to '+CONTACT+' with a screenshot, destination if safely available and approximate time. Do not click a suspicious ad to gather evidence. The team should review blocked categories and placements and escalate provider reports.'),
            ('Changes and rollout', 'Notify users before a material new ad purpose or provider becomes active and renew choices where required. Publish the provider inventory and approved effective date with the release. Keep records of ad-network and CMP configuration changes. For privacy concerns, email '+CONTACT+'.'),
         ], 'Public policy'),
        ('17_Browser_App_Installation_and_Device_Guide.docx', 'Browser App Installation and Device Guide', 'Getting started',
         'Install a browser-managed Alphajournal app when your browser supports it, or continue using the same service in a browser tab.', [
            ('Before installation', 'Open the legitimate Alphajournal site in a supported browser over HTTPS. Use the same account you normally use. Installation is optional and does not cost money, buy a subscription, accept cookies or grant notification, microphone or file permissions. The website remains usable without installation.'),
            ('Chrome and Edge', 'When the browser makes installation available, the app can show Install Alphajournal. Choose Install app to open the browser confirmation, then follow the browser instructions. You can also look for Install app in the address bar or browser menu. Menu labels vary by browser and operating system. A missing install action is not evidence that your account has a problem.'),
            ('iPhone and iPad', 'Open the site in Safari, use Share and choose Add to Home Screen where available, then confirm the name and add it. If you are inside a social or email app browser, first open the page in Safari. Browser and OS versions can change the available options; use their current installation guidance.'),
            ('Mac and other browsers', 'Supported Safari versions offer Add to Dock from the File menu. Other browsers may offer a site shortcut rather than a full installed web app. Use the browser menu if no automatic prompt is available. Native application downloads and app-store availability are separate from browser installation.'),
            ('Dismiss and try later', 'Choose Not now to suppress automatic install suggestions for seven days on this browser. Help and policies still provides installation guidance and a manual install button when a browser event is available. An accepted browser prompt is not shown as a confirmed installation until the browser reports installation. Standalone windows suppress the suggestion.'),
            ('Connectivity and updates', 'Signing in, syncing, fetching account data and most workspace operations require a network connection. This release does not promise offline editing or background synchronisation. Keep important work saved and verify sync before disconnecting. Updates normally load from the hosted service; reload after saving if an update is available. Do not clear storage to fix an issue before checking for unsynchronised work.'),
            ('Permissions and notifications', 'Installing does not grant notifications, microphone, camera or file access. Grant a permission only when intentionally using a feature that needs it. Browser and OS settings control revocation. A website permission and an in-app notification preference may both be required; neither is advertising consent.'),
            ('Uninstall and account deletion', 'Use your operating system or browser app manager to remove the installed app or shortcut. This does not cancel a subscription or delete the server account. To delete account data, use the in-app deletion controls and review the retention policy. Site data can remain after uninstall; clearing it can remove local settings and unsynchronised content.'),
            ('Troubleshooting', 'If Install app is unavailable, check whether the app is already installed, open it in a regular browser window instead of an embedded or private browser, and try the browser menu. Organisation-managed devices can restrict installation. If installation fails, continue in the browser and send a redacted description with browser and OS versions to '+CONTACT+'.'),
         ], 'User guide'),
        ('18_Workspace_User_Guide_and_FAQ.docx', 'Workspace User Guide and Frequently Asked Questions', 'Getting started',
         'A practical starting point for using Alphajournal, finding controls and understanding the limits of the workspace.', [
            ('Start with your account', 'Create or sign in to your account, review your profile and choose the appropriate workspace. Use a unique password and keep verification messages private. Feature access depends on your account role, current plan and deployment. A visible preview does not prove that a connected service is live.'),
            ('Record and review trades', 'Open the journal area and record the instrument, direction, entry and exit information, size, fees and review notes supported by the form. Verify currencies, time zones and imported values before relying on summaries. Use consistent tags and strategies so later review is useful. A journal entry records analysis; it is not a broker order.'),
            ('Research notes and strategies', 'Use notes for research and strategies for a repeatable plan. Review visibility before publishing or sharing. Keep passwords, brokerage credentials and third-party confidential material out of notes and attachments. Confirm that saved changes appear in the intended account before closing a session.'),
            ('Charts and AI tools', 'Check source, time, units and market availability before interpreting charts. AI may produce incorrect facts, calculations and assumptions. Review output and verify it independently. Sending a prompt to an enabled external AI service is separate from storing a local journal entry; consult the provider disclosure before sending confidential data.'),
            ('Community and messages', 'Choose what to share, check audience settings and follow the Community Guidelines. Public posts can be copied by other people. Use available report or block actions for spam and abuse. Avoid sending money, credentials or identity documents in response to unsolicited investment messages.'),
            ('Settings and personalisation', 'Appearance changes theme and density where supported. Notification settings control product preferences; device permissions are separate. Privacy settings control available visibility, export and deletion options. Help and policies contains the complete document library, cookie preferences, installation guide and contact details.'),
            ('Free access and billing', 'Free access may be supported by Google AdSense after rollout. Review the actual checkout for limits, taxes, renewal and ad treatment. Do not infer payment success from a selected plan. For a missing entitlement, preserve the receipt and contact support; do not pay again simply because the interface has not refreshed.'),
            ('Why was my work not saved', 'Check connectivity and whether you are signed in to the expected account. Keep the unsaved text and retry the explicit save action if present. Do not clear site data or uninstall while unsynchronised work is important. Report the affected screen, time and any visible error without sending sensitive records.'),
            ('How do I export or delete data', 'Open Privacy settings and use the available export and deletion controls. Review the deletion scope and confirmation carefully. Download and inspect any export before destructive actions. Billing cancellation and account deletion are separate. If a control is unavailable, request help at '+CONTACT+'; response timing and identity verification depend on the request and applicable law.'),
            ('How do I change cookies or install the app', 'Use Cookie preferences in Help and policies to save or reject optional choices. To install, use Install app when available or read the browser-specific instructions. Neither installation nor cookie acceptance upgrades your plan. Choices are local to a browser or device.'),
            ('Where can I get help', 'Search this library by topic or policy text. For assistance email '+CONTACT+' with the screen, problem, expected behaviour, time and device details. Support does not ask for passwords or one-time codes. No guaranteed response SLA or market-data performance is implied by this guide.'),
         ], 'User guide'),
        ('19_Support_Complaints_and_Privacy_Requests.docx', 'Support Complaints and Privacy Requests', 'Account and support',
         'Use the following routes to report a problem, dispute a transaction, request privacy assistance or report harmful content.', [
            ('Current contact', 'Email '+CONTACT+' for support, privacy, advertising and security concerns. Use a clear subject such as Account support, Billing review, Privacy request, Security report or Advertising report. This mailbox is the current contact supplied by the operator; no delivery or response-time guarantee is implied.'),
            ('Information to include', 'Include the account email if needed to locate your account, affected screen, date and time, device and browser version, reproduction steps and expected outcome. For billing include a transaction reference and a redacted receipt. Do not include passwords, session tokens, one-time codes, full card or bank numbers, or unnecessary trading records.'),
            ('Support form availability', 'The in-app ticket form sends only when a support service has been connected. A disabled form is not a submitted ticket. A failed request should retain your message for retry. Opening an email draft does not send it; review and send it in your email app. If no email app opens, copy the contact address.'),
            ('Privacy requests', 'Describe whether you need access, correction, export, erasure, consent withdrawal or help with visibility. We may ask for proportionate identity verification using a secure route. Never send identity documents unsolicited to a general mailbox. Request scope, applicable rights, exceptions and timelines must be assessed under the law that applies to you.'),
            ('Complaints and escalation', 'Keep your original correspondence and reference any case identifier in follow-ups. Explain why a previous response did not resolve the issue and the outcome you seek. The current contact above handles complaints and privacy requests. Applicable statutory complaint and response rights remain available. This process does not limit statutory consumer or regulatory remedies.'),
            ('Security and urgent issues', 'For suspected compromise, stop sharing credentials, change passwords through trusted controls and contact support. Report vulnerabilities privately with minimal proof that avoids other users data. This mailbox is not an emergency service. Contact relevant emergency or financial institutions directly for immediate threats or unauthorised payments.'),
            ('Handling and retention', 'Support information should be restricted to staff and processors resolving the case. Preserve only the evidence needed for resolution and applicable legal duties. Confirm retention periods and escalation ownership before publishing a fixed promise. Requests to remove a support record may be limited by an ongoing dispute or statutory retention requirement.'),
         ], 'User guide'),
        ('20_Accessibility_and_Device_Permissions_Guide.docx', 'Accessibility and Device Permissions Guide', 'Account and support',
         'Adjust the experience and understand what device access means before granting it.', [
            ('Reading and navigation', 'Use browser zoom, system text sizing, keyboard navigation and your screen reader as appropriate. The help library uses headings, labelled controls and expandable sections. If content is clipped or a control is difficult to reach, report the screen, device, text scale and assistive technology to '+CONTACT+'. No independent accessibility certification is claimed.'),
            ('Theme and motion', 'Use the appearance controls offered by the app and system accessibility preferences. Contrast, focus and motion should be checked in both light and dark themes at release. Installation prompts and cookie choices should remain readable on small screens and at larger text sizes.'),
            ('Microphone and speech', 'A supported dictation or voice feature may request microphone access when you invoke it. Review the permission prompt and any speech-processing disclosure. Declining should leave typed input available where the feature supports it. Revoke microphone access in browser or OS settings when no longer needed.'),
            ('Files and attachments', 'A file picker gives access to the selected file or files; review what you select before upload. Attachments may contain names, account numbers or hidden metadata. Remove sensitive information before sharing and check the destination visibility. Do not grant broad access merely to read a policy or install the browser app.'),
            ('Notifications', 'Notification preferences in the app do not override browser or OS permission. Grant permission only when you want supported notifications. Delivery can be affected by connectivity, battery settings, permissions and platform restrictions. Do not depend on notifications as a guaranteed trading or risk alert service.'),
            ('Location camera and advertising identifiers', 'No blanket location or camera permission is required to read help or use cookie choices. Any future feature using additional access needs a clear purpose at the point of request. A browser consent screen is not iOS App Tracking Transparency permission and must not be presented as granting it.'),
            ('Revocation and shared devices', 'Use browser site settings or OS application settings to review permissions. Sign out on shared devices and avoid saving credentials. Clearing storage may erase unsynchronised work and consent preferences. Revoking a device permission does not delete server-side content or cancel billing.'),
         ], 'User guide'),
        ('21_Storage_Vendor_and_Retention_Register.docx', 'Storage Vendor and Retention Register', 'Publication resources',
         'A repository-based inventory and deployment worksheet for verifying the public notices. This is a release resource, not a completed production processor register.', [
            ('Consent preference', 'SharedPreferences key alphajournal_consent_v1; owner Alphajournal; purpose remember optional choices; fields schema version, UTC saved time, analytics, advertising, personalised ads and affiliate choice; validity 180 days; renewed on a saved choice; rejection does not delete the necessary preference record. Browser key names may be prefixed flutter. Verify the built app storage backend.'),
            ('Install suggestion', 'Web local-storage key alphajournal_install_dismissed_v1; owner Alphajournal; value last dismissal time; purpose avoid repeated installation prompts; suppression seven days; physical timestamp retained until overwritten or cleared. No third-party request is made by app_install.js.'),
            ('Affiliate attribution', 'SharedPreferences affiliate_attribution_v1 and affiliate_visitor_v1; purpose optional automatic referral attribution and campaign click measurement; valid referral window less than 30 days; removal on rejection or withdrawal, invalid or expired attribution, and completed conversion. Manual signup codes remain a separate user-requested input. Verify server click records and their retention separately.'),
            ('Authentication and workspace preferences', 'Source auth_session_storage.dart uses auth_session_user_id, auth_session_email, auth_session_role, auth_session_profile, auth_session_affiliate_profile, auth_session_token, auth_session_timestamp, auth_has_seen_onboarding, app_scaffold_last_destination and auth_workspace_role_<userId>. The authentication SDK may use additional session storage. These are account/session or requested preference records, not advertising categories. Do not publish an invented uniform expiry: test logout, refresh, account switching, deletion and SDK behaviour.'),
            ('Workspace caches and content', 'The repository includes local workspace preferences and caches such as alphajournal_affiliate_workspace_v2_inr, note drafts and other feature-specific records. Enumerate actual local storage, IndexedDB, cookies and Cache Storage on clean production profiles. This list is a starting inventory, not an exhaustive deployment audit. Record each name, owner, purpose, data fields, storage mechanism, retention and removal trigger.'),
            ('Google AdSense', 'Planned; no tag currently enabled. Before rollout enter publisher ID, account owner, supported sites, processors, allowed locations, ad formats, active cookie names and durations observed in a production-like audit, CMP identity and version, regional rules, opt-out links and removal limits. Do not list example Google cookie names as observed facts.'),
            ('Other providers', 'The source includes Supabase-backed account/data services, payment integrations, Google Fonts and optional AI/external links. Configuration and actual traffic determine which vendors are live. Verify hosting, auth, email, billing, analytics, AI, content delivery and error reporting independently. Record legal vendor name, role, purpose, data, location, contract, retention and contact. Never copy credentials or secret environment values into this register.'),
            ('Retention approval worksheet', 'For account profiles, private content, public posts, messages, attachments, support tickets, security logs, consent evidence, referral clicks, invoices, affiliate tax records and backups, assign an owner and approve a duration or clear deletion criterion. Record legal basis, active-system purge, backup expiration, vendor deletion and verification. Unconfirmed periods remain release blockers, not promises to users.'),
            ('Audit procedure', 'Start with a clean browser and record storage and requests before interaction. Repeat reject, granular accept, all accept, withdrawal, refresh, expiry, sign-in, sign-out and installation. Inspect URLs and payloads for private data. Compare authenticated and public routes and paid/free eligibility. Capture browser version, build hash, time, observer and findings without retaining credentials.'),
         ], 'Release resource'),
        ('22_Consent_Advertising_and_Installation_Implementation_Guide.docx', 'Consent Advertising and Installation Implementation Guide', 'Publication resources',
         'Engineering and operational requirements for the implemented choices and installation experience, and the remaining Google AdSense launch work.', [
            ('Architecture', 'ConsentController owns local versioned choices through SharedPreferences. Optional categories fail closed when records are missing, corrupt, expired or from a different schema. CookiePreferencesDialog is shared by the first web visit and help centre. BrowserExperienceGate sequences the cookie notice before any eligible install suggestion. Native builds provide help without a browser installation prompt.'),
            ('Future ad integration contract', 'No advertising SDK is loaded by this release. Before adding one, create an adapter that waits for known local consent, required CMP approval, verified free-plan eligibility and a reviewed public-content route. Recheck permission before every request and stop listeners or tear down optional SDKs on withdrawal. Do not initialise vendor tags in index.html, preconnect to ad endpoints before choice or send cookieless pings on an assumed exemption. Keep optional requests off when eligibility or consent is unknown.'),
            ('Google regional requirements', 'Google requires a certified CMP integrated with its required TCF framework for covered publisher use in the EEA, UK and Switzerland. Check the current Google policy and the CMP product scope before launch. Configure consent messages, vendor purposes, regional handling, withdrawal entry point and required privacy signals. This local preference UI is not certified and does not issue a TC string. A CMP configuration needs network validation and production review.'),
            ('Affiliate behaviour', 'Automatic capture and load are gated by the affiliate choice. Reject and withdrawal remove attribution and visitor records. A referral carried in the current signup URL can be captured after an affirmative choice. Do not backfill pre-consent click events. Manual referral entry remains available as a deliberate user request. Check expiry and complete-conversion cleanup.'),
            ('Install bridge', 'web/app_install.js captures beforeinstallprompt before Flutter bootstrap, prevents the default browser promotion, stores the event and exposes snapshot, subscribe, prompt and dismiss methods. A direct user action calls prompt; each event is consumed once. appinstalled or standalone display confirms installed state. Seven-day dismissal is remembered when storage is available, and in-memory dismissal still works when it is blocked. Manual instructions cover browsers without the event.'),
            ('Consent test matrix', 'Verify no optional activity before a choice; equal accept/reject access; each category saves independently; personalisation cannot survive advertising rejection; choices survive reload; reject clears referral data; failures display errors and keep optional tracking off; corrupt, future-dated, expired and old-schema values are treated as unknown; closing does not grant consent; links work without sign-in; two browser profiles remain independent.'),
            ('Installation test matrix', 'Verify a late and an early beforeinstallprompt event, direct-button activation, one event consumed once, acceptance, dismissal, exception, appinstalled, standalone mode, blocked storage and a seven-day cooldown. Test desktop Chrome/Edge and manual Safari instructions on real target devices. Browser eligibility can depend on HTTPS, manifest validity, browser heuristics and user settings; a unit test alone does not certify installability.'),
            ('Ad rollout acceptance', 'Verify approved publisher account, active provider disclosures, correct CMP and region configuration, permitted placements, ads.txt where required, no private route scans or sensitive URL data, no ads on blocked or unknown entitlements, no requests after withdrawal, mobile layout and accessible ad labels. Monitor invalid traffic and use provider-supported testing; never click live ads to test revenue.'),
            ('Documentation and versioning', 'generate_documents.py and publication_expansion.py produce Word, Markdown and assets/legal/publication_library.json from a shared source. The app reads the JSON bundle, so policy content is available without a document download. Policies and guides carry their current update date. Keep accepted versions and publication history aligned with the service. Bump consent schema when new purposes require a new choice, archive old policy versions and record the build and approval owner.'),
            ('Publication blockers', 'Complete registered legal identity/address and grievance contact, retention schedule, processor register, terms venue/liability review, payment promises and affiliate tax/rate reconciliation. Configure support delivery and Google AdSense/CMP before describing them as live. Confirm the actual operating arrangements and obtain appropriate legal review for material legal changes. The current work implements product controls and user-facing policy content; it does not certify legal compliance or activate revenue.'),
            ('Reference sources', 'Reviewed 9 November 2026: Google publisher CMP requirements https://support.google.com/adsense/answer/13554116 ; Google partner-site privacy https://policies.google.com/technologies/partner-sites ; Google ads technologies https://policies.google.com/technologies/ads ; MDN installation event https://developer.mozilla.org/en-US/docs/Web/API/Window/beforeinstallprompt_event ; web.dev installation guide https://web.dev/learn/pwa/installation-prompt ; ICO storage and access guidance https://ico.org.uk/for-organisations/direct-marketing-and-privacy-and-electronic-communications/guidance-on-the-use-of-storage-and-access-technologies/ . Recheck at deployment.'),
         ], 'Release resource'),
        ('23_Help_Centre_Release_Notes.docx', 'Help Centre Release Notes', 'Getting started',
         'AlphaJournal 1.0.0 build 1 establishes the application capability baseline, entitlement boundaries, release versioning, installation flow, and automatic update checks. These notes describe repository readiness and do not by themselves announce a production deployment.', [
            ('Versioning and automatic updates', 'The canonical version is 1.0.0+1 in pubspec.yaml and is propagated to supported Flutter platforms. AlphaJournal checks a small static HTTPS release manifest, caches the result for six hours, shows recommended or required update prompts, reloads current web assets safely, and sends native users to the signed store or download channel. Version checks do not query Supabase.'),
            ('Workspace records', 'Writing Desk, Trade Journal, linked Markdown Notes, and Strategy Playbooks connect executions, theses, revisions, attachments, analytics, ticker links, public/private sharing, and eligible PDF exports in one workspace.'),
            ('Calculators and market data', 'The application includes 22 trading, options, investing, currency, and Indian tax calculators. Free users retain core tools; Basic and Pro unlock advanced tools. Full Market Intelligence includes overview, one consolidated World Indices table, one consolidated Assets table, movers, instruments, news, screeners, quote history, and instrument details. Free users receive only the approved lightweight Community market preview.'),
            ('Community and private messaging', 'Community supports public posts, setups, charts, polls, reactions, bookmarks, reposts, quote posts, threaded replies, profiles, follows, moderation, live spaces, and shareable snapshots. Private Messages are restricted to Basic and Pro and support encrypted conversations, recovery keys, attachments, voice notes, and shared workspace cards.'),
            ('Unified AI and notifications', 'The gateway-first Unified AI service preserves multi-provider fallback behavior, streaming, search and research modes, specialist trading workflows, citations, memory, schedules, voice, and saved pages. Activity inbox and web push surfaces route mentions, replies, security events, and other supported notifications.'),
            ('Subscriptions, affiliate, and administration', 'Free, Basic, and Pro entitlements are applied before navigation and before paid network work starts. Billing management, purchase restoration, quota displays, referral applications and attribution, affiliate campaign/payout workspaces, and the server-verified Admin console are included in the operational surface. Paid monthly checkout remains disabled until production provider products, signing, webhooks, and store review are complete.'),
            ('Installation and deep links', 'The PWA install bridge remembers dismissals, detects supported installed related apps, preserves the requested HTTPS route when handing off to an installed app, and remains on the matching web route when no app is installed. Cross-subdomain session continuity remains intentional across approved AlphaJournal hosts.'),
            ('Help, privacy, and accessibility', 'Help and policies includes the searchable document library, release notes, installation guidance, support, cookie and consent controls, privacy/data controls, trading and AI risk notices, and an application version card. Responsive layouts, themes, text scaling, keyboard focus, reduced motion, and shared AlphaJournal components remain required.'),
            ('Security and efficiency', 'Paid features are protected at route, presentation, repository/service, and server/database boundaries where applicable. Market and update reads use bounded data, caching, pagination, lazy loading, and request deduplication. Secrets, private data, and exploitable vulnerability details remain outside public reports and client bundles.'),
            ('Deployment responsibilities', 'A release owner must bump pubspec version/build metadata, update CHANGELOG.md, regenerate the selected platform manifest entry, validate tests and analysis, publish signed native builds through their official channel, and use minimum-supported versions only for a verified security or compatibility requirement.'),
         ], 'User guide'),
    ]
    for filename, title, group, intro, sections, kind in new:
        spec = policy('Alphajournal '+title, intro, sections, kind=kind)
        spec['group'] = group
        docs.append((filename, spec))
    groups = {1:'Privacy and advertising',2:'Terms and safety',3:'Privacy and advertising',4:'Publication resources',5:'Account and support',6:'Terms and safety',7:'Terms and safety',8:'Terms and safety',9:'Terms and safety',10:'Affiliate programme',11:'Affiliate programme',12:'Affiliate programme',13:'Account and support',14:'Account and support',15:'Publication resources'}
    slugs = ['privacy','terms','cookies','consent-specification','refunds','trading-risk','eula','acceptable-use','community','affiliate-agreement','affiliate-marketing','affiliate-payouts','account-deletion','security','publication-guide','advertising','install','user-guide','support','accessibility','storage-register','implementation','release-notes']
    for (filename, spec), slug in zip(docs, slugs):
        number = int(filename[:2])
        spec['id'] = slug
        spec.setdefault('group', groups.get(number))
        spec['updated'] = UPDATED
        if slug == 'release-notes':
            spec['updated'] = '2026-11-19'
        spec['status'] = 'Guide' if spec['kind'] == 'User guide' else ('Release resource' if number in (4,15,21,22) else 'Policy')
    return docs
